import { useState } from "react";
import { useNavigate } from "react-router-dom";
import "../styles/Signup.css";
import seefoodLogo from "../assets/images/seefood-logo.jpg"; // adjust path if needed

export default function Signup() {
  const navigate = useNavigate();

  // Form state
  const [email, setEmail] = useState("");
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [gender, setGender] = useState("");
  const [age, setAge] = useState("");
  const [height, setHeight] = useState("");
  const [weight, setWeight] = useState("");
  const [workout, setWorkout] = useState("");
  const [activity, setActivity] = useState("");
  const [agreed, setAgreed] = useState(false);

  // UI state
  const [error, setError] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [showConfirmPw, setShowConfirmPw] = useState(false);

  const handleSubmit = () => {
    setError("");

    // Required fields check
    if (
      !email.trim() ||
      !firstName.trim() ||
      !lastName.trim() ||
      !password ||
      !confirmPassword ||
      !gender ||
      !age ||
      !height ||
      !weight ||
      !workout ||
      !activity
    ) {
      setError("Please fill in all required fields.");
      return;
    }

    // Password match
    if (password !== confirmPassword) {
      setError("Passwords do not match.");
      return;
    }

    // Terms
    if (!agreed) {
      setError("You must agree to the Terms and Conditions.");
      return;
    }

    // OK -> go to login (dummy flow)
    navigate("/login");
  };

  return (
    <div className="signup-page">
      {/* LEFT BRAND PANEL */}
      <div className="signup-left">
        <div className="brand">
          <img src={seefoodLogo} alt="SeeFood logo" className="brand-logo" />
          <div className="brand-name">SeeFood</div>
        </div>

        <h1>Create your account</h1>
        <p>
          Set up your profile once, then SeeFood can personalize nutrition insights and meal
          suggestions based on your lifestyle.
        </p>

        <div className="left-badges">
          <div className="badge">Personal Profile</div>
          <div className="badge">Nutrition Tracking</div>
          <div className="badge">Smart Meal Prep</div>
        </div>

        <div className="left-footer">IM3180 • Group IE01</div>
      </div>

      {/* RIGHT FORM PANEL */}
      <div className="signup-right">
        <div className="signup-card">
          <div className="signup-header">
            <h2>Sign up</h2>
            <p>Fill in your details to get started.</p>
          </div>

          {/* EMAIL */}
          <div className="field">
            <label>Email</label>
            <input
              type="email"
              placeholder="example@email.com"
              className="signup-input"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>

          {/* NAME */}
          <div className="grid-2">
            <div className="field">
              <label>First Name</label>
              <input
                type="text"
                placeholder="First Name"
                className="signup-input"
                value={firstName}
                onChange={(e) => setFirstName(e.target.value)}
              />
            </div>

            <div className="field">
              <label>Last Name</label>
              <input
                type="text"
                placeholder="Last Name"
                className="signup-input"
                value={lastName}
                onChange={(e) => setLastName(e.target.value)}
              />
            </div>
          </div>

          {/* PASSWORDS */}
          <div className="grid-2">
            <div className="field">
              <label>Password</label>
              <div className="password-wrap">
                <input
                  type={showPw ? "text" : "password"}
                  placeholder="Create a password"
                  className="signup-input"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                <button
                  type="button"
                  className="show-btn"
                  onClick={() => setShowPw((v) => !v)}
                >
                  {showPw ? "Hide" : "Show"}
                </button>
              </div>
            </div>

            <div className="field">
              <label>Confirm Password</label>
              <div className="password-wrap">
                <input
                  type={showConfirmPw ? "text" : "password"}
                  placeholder="Confirm password"
                  className="signup-input"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                />
                <button
                  type="button"
                  className="show-btn"
                  onClick={() => setShowConfirmPw((v) => !v)}
                >
                  {showConfirmPw ? "Hide" : "Show"}
                </button>
              </div>
            </div>
          </div>

          {/* GENDER + WORKOUT */}
          <div className="grid-2">
            <div className="field">
              <label>Gender</label>
              <select
                className="signup-input"
                value={gender}
                onChange={(e) => setGender(e.target.value)}
              >
                <option value="">Select</option>
                <option>Male</option>
                <option>Female</option>
                <option>Prefer not to say</option>
              </select>
            </div>

            <div className="field">
              <label>Workout Frequency</label>
              <select
                className="signup-input"
                value={workout}
                onChange={(e) => setWorkout(e.target.value)}
              >
                <option value="">Select</option>
                <option>Never</option>
                <option>1–2 times per week</option>
                <option>3–4 times per week</option>
                <option>5–6 times per week</option>
                <option>Daily</option>
              </select>
            </div>
          </div>

          {/* AGE / HEIGHT / WEIGHT */}
          <div className="grid-3">
            <div className="field">
              <label>Age</label>
              <input
                type="number"
                placeholder="Age"
                className="signup-input"
                value={age}
                onChange={(e) => setAge(e.target.value)}
              />
            </div>

            <div className="field">
              <label>Height (cm)</label>
              <input
                type="number"
                placeholder="e.g. 165"
                className="signup-input"
                value={height}
                onChange={(e) => setHeight(e.target.value)}
              />
            </div>

            <div className="field">
              <label>Weight (kg)</label>
              <input
                type="number"
                placeholder="e.g. 60"
                className="signup-input"
                value={weight}
                onChange={(e) => setWeight(e.target.value)}
              />
            </div>
          </div>

          {/* ACTIVITY LEVEL */}
          <div className="activity-section">
            <div className="activity-title">Activeness Level</div>

            <label className="activity-option">
              <input
                type="radio"
                name="activity"
                value="sedentary"
                checked={activity === "sedentary"}
                onChange={(e) => setActivity(e.target.value)}
              />
              <div className="activity-text">
                <strong>Sedentary</strong>
                <span>Little to no activity, desk bound</span>
              </div>
            </label>

            <label className="activity-option">
              <input
                type="radio"
                name="activity"
                value="light"
                checked={activity === "light"}
                onChange={(e) => setActivity(e.target.value)}
              />
              <div className="activity-text">
                <strong>Light</strong>
                <span>Light activity, some standing and walking</span>
              </div>
            </label>

            <label className="activity-option">
              <input
                type="radio"
                name="activity"
                value="moderate"
                checked={activity === "moderate"}
                onChange={(e) => setActivity(e.target.value)}
              />
              <div className="activity-text">
                <strong>Moderate</strong>
                <span>On feet most days, moderate activity</span>
              </div>
            </label>

            <label className="activity-option">
              <input
                type="radio"
                name="activity"
                value="high"
                checked={activity === "high"}
                onChange={(e) => setActivity(e.target.value)}
              />
              <div className="activity-text">
                <strong>High</strong>
                <span>Workout and exercise routinely</span>
              </div>
            </label>
          </div>

          {/* TERMS */}
          <label className="terms">
            <input
              type="checkbox"
              checked={agreed}
              onChange={(e) => setAgreed(e.target.checked)}
            />
            <span>
              I agree with the <span className="fake-link">Terms</span> and{" "}
              <span className="fake-link">Privacy Policy</span>.
            </span>
          </label>

          {/* SUBMIT */}
          <button className="primary-btn" onClick={handleSubmit}>
            Continue
          </button>

          {/* ERROR */}
          {error && <div className="signup-error">{error}</div>}

          <p className="login-text">
            Already have an account?{" "}
            <span className="login-link" onClick={() => navigate("/login")}>
              Log in
            </span>
          </p>
        </div>
      </div>
    </div>
  );
}
